using System;
using System.Collections.Generic;
using System.Linq;

namespace OpenFPS.Client.AudioEngine.Core.Nature;

/// <summary>
/// The recorded shores the wave models are held to (docs/WAVES_AND_SHORES.md section 8): the texture
/// statistics (TextureStatistics, McDermott and Simoncelli 2011) of each recording in 20 s pieces, as
/// TextureStatistics keeps the fountain's, the rain's and the creeks', measured with tools/texture_stats.py.
/// The recordings are in ~/openfps-scratch-archive/waves-2026-10-06/refs with SOURCES.txt; they are
/// yardsticks and are never played or shipped, so their numbers are written here for the tests.
/// </summary>
public static class ShoreReferences
{
    /// <summary>The fourteen statistics the nature models are fitted on (NatureTests, RunningWaterTests).</summary>
    public static readonly string[] FittedKeys =
    {
        "cv 1-3k", "cv 3-6k", "cv 6-12k", "skew 1-3k", "skew 3-6k", "skew 6-12k", "kurt 3-6k", "kurt 6-12k",
        "corr near", "corr octave", "corr far", "mod slow", "mod mid", "mod fast",
    };

    public static bool Has(string texture) => Rows.TryGetValue(texture, out var r) && r.Length > 0;

    public static IReadOnlyList<(string File, IReadOnlyDictionary<string, double> Summary)> References(string texture)
        => Rows[texture].Select(r => (r.File, (IReadOnlyDictionary<string, double>)TextureStatistics.Keys
                                                .Select((k, i) => (k, r.Values[i])).ToDictionary(p => p.k, p => p.Item2))).ToList();

    /// <summary>The recordings' range of one statistic.</summary>
    public static (double Min, double Max) Range(string texture, string key)
    {
        var rows = References(texture);
        return (rows.Min(r => r.Summary[key]), rows.Max(r => r.Summary[key]));
    }

    /// <summary>The 10 ms 4-16 kHz waveform kurtosis of each kind's recordings (TextureStatistics.Waveform,
